package com.cedarsoftware.util;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.*;
import org.mockito.junit.jupiter.MockitoExtension;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

@ExtendWith(MockitoExtension.class)
class TestUtil_isReleaseMode_Test {

    /**
     * Holds the original value of the {@code performRelease} system property before each test.
     */
    private String originalPerformRelease;

    @BeforeEach
    void setupBeforeEach() {
        // Capture the current value (may be {@code null}) so we can restore it later.
        originalPerformRelease = System.getProperty("performRelease");
    }

    @AfterEach
    void teardownAfterEach() {
        // Restore the original value (or clear the property if it was not set).
        if (originalPerformRelease == null) {
            System.clearProperty("performRelease");
        } else {
            System.setProperty("performRelease", originalPerformRelease);
        }
    }

    @Test
    void isReleaseMode_whenPropertyTrue_returnsTrue() {
        // given
        System.setProperty("performRelease", "true");
        // when
        boolean result = TestUtil.isReleaseMode();
        // then
        assertTrue(result, "isReleaseMode() should return true when performRelease='true'");
    }

    @Test
    void isReleaseMode_whenPropertyFalse_returnsFalse() {
        // given
        System.setProperty("performRelease", "false");
        // when
        boolean result = TestUtil.isReleaseMode();
        // then
        assertFalse(result, "isReleaseMode() should return false when performRelease='false'");
    }

    @Test
    void isReleaseMode_whenPropertyAbsent_returnsFalse() {
        // given
        System.clearProperty("performRelease");
        // when
        boolean result = TestUtil.isReleaseMode();
        // then
        assertFalse(result, "isReleaseMode() should default to false when performRelease is not set");
    }

    @Test
    void isReleaseMode_whenPropertyIsNonBoolean_returnsFalse() {
        // given
        System.setProperty("performRelease", "notABoolean");
        // when
        boolean result = TestUtil.isReleaseMode();
        // then
        assertFalse(result, "isReleaseMode() should return false for non‑boolean values");
    }

    /**
     * Verifies the behaviour when the {@code performRelease} property is explicitly set
     * to various values (including different capitalisations, whitespace, numeric strings,
     * and completely unrelated strings). The expected result follows the contract of
     * {@link Boolean#parseBoolean(String)} – only a case‑insensitive exact match of {@code "true"}
     * yields {@code true}; everything else yields {@code false}.
     *
     * @param propertyValue the value to store in the system property (empty string allowed)
     * @param expected      the expected boolean result from {@link TestUtil#isReleaseMode()}
     * @param description   a short human‑readable description of the case (used in the test name)
     */
    @ParameterizedTest(name = "[{index}] {2} => \"{0}\" → {1}")
    @CsvSource({ // standard true/false values
    "true,   true,   'lower‑case true'", "false,  false,  'lower‑case false'", "TRUE,   true,   'upper‑case TRUE'", "TrUe,   true,   'mixed‑case true'", "FALSE,  false,  'upper‑case FALSE'", "FaLsE,  false,  'mixed‑case FALSE'", // whitespace handling (Boolean.parseBoolean does NOT trim)
    "' true', false,  'leading whitespace'", "'true ', false,  'trailing whitespace'", // non‑boolean literals
    "yes,    false,  'non‑boolean word yes'", "no,     false,  'non‑boolean word no'", "null,   false,  'literal string \"null\"'", "'',     false,  'empty string'", // numeric strings
    "1,      false,  'numeric string 1'", "0,      false,  'numeric string 0'", // long non‑boolean that starts with true but has extra characters
    ", false, 'long non‑boolean starting with true'" })
    void isReleaseMode_variousPropertyValues(String propertyValue, boolean expected, String description) {
        // given – set or clear the system property according to the test data
        if ("<absent>".equals(propertyValue)) {
            System.clearProperty("performRelease");
        } else {
            System.setProperty("performRelease", propertyValue);
        }
        // when
        boolean actual = TestUtil.isReleaseMode();
        // then
        assertEquals(expected, actual, () -> String.format("Property value \"%s\" should result in %s (%s)", propertyValue, expected, description));
    }
}
